    ['일반 특성', '조색이 끝난 후 별도의 상도 투명 클리어(Clearcoat) 도장이 아예 필요 없는, 원스텝 22라인 우레탄 솔리드 원톤(상용 트럭, 버스, 구형 승용차 등) 컬러 전반의 절대적인 핵심 뼈대로 사용됩니다.'],
    ['외관 변화', '도막이 경화제로 건조된 후 별도의 투명 클리어를 덮은 것처럼 안료 위로 수지가 떠오릅니다. 젤리처럼 맑고 깊은 묵직한 고광택(High Gloss) 층을 도막 자체적으로 융합하여 발현하는 엄청난 볼륨감을 자랑합니다.'],
    ['배합 비율', '22라인 솔리드 컬러 데이터 현장 조색 시, 색상 안료들을 띄우기 위한 거대한 베이스 그릇 역할을 하므로 레시피 전체에서 가장 무겁고 가장 다량으로 투입되어 기본 베이스를 든든하게 구성합니다.'],
    ['비교 분석', '[경고] 반드시 규격에 맞는 22라인 전용 2K 경화제와 정해진 스펙 혼합 비율(일반적으로 2:1)로 섞어야 합니다. 비율이 조금이라도 틀어지면 속이 미경화 되어 찐득거리거나, 겉 도막이 쩍쩍 갈라지는 크랙 하자가 직빵으로 발생하므로 전자저울이 필수입니다.']
